select null, t.id, 'builtin', 'The standard operating temperature of a steam autoclave is:', '["72 °C","100 °C","121 °C","170 °C"]'::jsonb, 2, 'Autoclaves usually run at 121 °C (sometimes 132 °C) at 15–20 psi, typically for 20 minutes or more; the high temperature, not the pressure itself, kills endospores. 72 °C for 15 s is HTST pasteurization, and up to 170 °C for at least 2 hours is dry heat. Reference: OpenStax Microbiology, 13.2 Using Physical Methods to Control Microorganisms (openstax.org/books/microbiology/pages/13-2-using-physical-methods-to-control-microorganisms).', '["Pasteurization temperature (HTST).","Boiling; does not kill all endospores.","Usually 15 psi for at least 15 minutes; kills endospores.","Dry-heat (hot-air oven) temperature."]'::jsonb, 1, 'verified'
