select null, t.id, 'builtin', 'HIV makes a DNA copy of its RNA genome using which enzyme?', '["DNA polymerase I","Reverse transcriptase","RNA-dependent RNA polymerase","DNA ligase"]'::jsonb, 1, 'HIV is a retrovirus: reverse transcriptase copies its RNA genome into DNA, which is then integrated into the host cell''s DNA. This enzyme is the target of reverse transcriptase inhibitors such as AZT. Reference: OpenStax Microbiology, 14.4 Mechanisms of Other Antimicrobial Drugs (openstax.org/books/microbiology/pages/14-4-mechanisms-of-other-antimicrobial-drugs).', '["Bacterial DNA repair and replication enzyme.","RNA-dependent DNA polymerase; target of NRTI and NNRTI drugs.","Used by RNA viruses like influenza, not retroviruses.","Joins DNA strands; HIV uses integrase to insert its DNA."]'::jsonb, 1, 'verified'
