insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'What is the correct order of reagents in the Gram stain?', '["Safranin → iodine → alcohol → crystal violet","Crystal violet → iodine → alcohol/acetone → safranin","Crystal violet → alcohol/acetone → iodine → safranin","Iodine → crystal violet → safranin → alcohol/acetone"]'::jsonb, 1, 'Crystal violet is the primary stain, Gram''s iodine the mordant, ethanol or acetone-alcohol the decolorizer, and safranin the counterstain. Leaving the decolorizer on too long can give false results. Reference: OpenStax Microbiology, 2.4 Staining Microscopic Specimens (openstax.org/books/microbiology/pages/2-4-staining-microscopic-specimens).', '["Reversed; safranin is the last step.","Primary stain, mordant, decolorizer, then counterstain.","Iodine must fix the dye before decolorizing.","Wrong order; crystal violet comes first."]'::jsonb, 1, 'verified'
