insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Gram-positive bacteria stay purple after decolorization because they have:', '["An outer membrane rich in lipopolysaccharide","A thick peptidoglycan layer in the cell wall","A polysaccharide capsule","Mycolic acids in the cell wall"]'::jsonb, 1, 'A thick peptidoglycan layer holds the crystal violet–iodine complex, so gram-positive cells resist the decolorizer. Gram-negative cells lose it and take up the pink safranin. Reference: OpenStax Microbiology, 2.4 Staining Microscopic Specimens (openstax.org/books/microbiology/pages/2-4-staining-microscopic-specimens).', '["That is the gram-negative wall; alcohol damages it, so the dye washes out.","Thick peptidoglycan traps the crystal violet-iodine complex.","Capsules do not decide the Gram reaction.","That is why mycobacteria are acid-fast."]'::jsonb, 1, 'verified'
