select null, t.id, 'builtin', 'Why is potassium hydroxide (KOH) added to skin, hair, or nail scrapings for fungal examination?', '["To stain the hyphae blue","To dissolve keratin so the hyphae can be seen","To kill bacteria before culture","To make yeast form germ tubes"]'::jsonb, 1, 'KOH dissolves the keratin in hair, nails, and skin cells, which lets fungal hyphae be seen under the microscope. Reference: OpenStax Microbiology, 21.4 Mycoses of the Skin (openstax.org/books/microbiology/pages/21-4-mycoses-of-the-skin).', '["KOH does not stain; lactophenol cotton blue does.","Clears keratin and cell debris to show fungal elements.","Not the purpose of KOH.","Germ tubes form in serum, not KOH."]'::jsonb, 1, 'verified'
