insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Which process kills all microbes, including endospores?', '["Disinfection","Antisepsis","Sterilization","Sanitization"]'::jsonb, 2, 'Sterilization kills vegetative cells, endospores, and viruses. Disinfection of objects doesn''t sterilize because endospores tend to survive, and antiseptics are chemicals safe for living skin or tissue. Reference: OpenStax Microbiology, 13.1 Controlling Microbial Growth (openstax.org/books/microbiology/pages/13-1-controlling-microbial-growth).', '["Kills most pathogens on objects, but not all endospores.","Disinfection of living tissue (skin).","Kills all life, including endospores.","Lowers microbes to safe public health levels."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'MICRO' and t.name = 'Lab Safety & Sterilization'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Which process kills all microbes, including endospores?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Kills most pathogens on objects, but not all endospores.","Disinfection of living tissue (skin).","Kills all life, including endospores.","Lowers microbes to safe public health levels."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Disinfection","Antisepsis","Sterilization","Sanitization"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Which process kills all microbes, including endospores?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
