select null, t.id, 'builtin', 'Which biological safety cabinet is gas-tight with attached rubber gloves and is used for highly infectious BSL-4 agents?', '["Class I","Class II","Class III","A laminar-flow clean bench"]'::jsonb, 2, 'Class III BSCs are designed for highly infectious agents like those in BSL-4 laboratories; the alternative at BSL-4 is a full-body positive-pressure suit. Reference: OpenStax Microbiology, 13.2 Using Physical Methods to Control Microorganisms (openstax.org/books/microbiology/pages/13-2-using-physical-methods-to-control-microorganisms).', '["Protects the worker and the room, not the sample.","Most common; protects the worker, sample and room.","Fully enclosed glove box for the most dangerous agents.","Protects the product only; not for infectious work."]'::jsonb, 2, 'verified'
