insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'HEPA filters used in biological safety cabinets have an effective pore size of about:', '["0.3 µm","3 µm","30 µm","0.003 µm"]'::jsonb, 0, 'HEPA filters have effective pore sizes of 0.3 µm, small enough to trap bacteria and many other particles in the air. Reference: OpenStax Microbiology, 13.2 Using Physical Methods to Control Microorganisms (openstax.org/books/microbiology/pages/13-2-using-physical-methods-to-control-microorganisms).', '["Removes at least 99.97% of particles 0.3 µm in size.","Too large to trap many bacteria.","Far too large.","Far smaller than needed; 0.3 µm is the HEPA test size."]'::jsonb, 2, 'verified'
