insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Dry-heat sterilization of glassware in a hot-air oven typically uses:', '["121 °C for 15 minutes","170 °C for about 2 hours","72 °C for 15 seconds","100 °C for 10 minutes"]'::jsonb, 1, 'Dry heat needs long exposure (at least 2 hours) at temperatures up to 170 °C in a dry-heat oven. 121 °C is moist heat (autoclave), and 72 °C for 15 s is pasteurization. Reference: OpenStax Microbiology, 13.2 Using Physical Methods to Control Microorganisms (openstax.org/books/microbiology/pages/13-2-using-physical-methods-to-control-microorganisms).', '["Steam autoclave settings.","Dry heat needs higher temperature and longer time than steam.","HTST pasteurization settings.","Boiling; does not sterilize."]'::jsonb, 1, 'verified'
