insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'High-temperature short-time (HTST) pasteurization of milk uses:', '["121 °C for 15 minutes, producing a sterile product","72 °C for 15 seconds, reducing but not eliminating microbes","170 °C for 2 hours","Gamma radiation"]'::jsonb, 1, 'HTST pasteurization exposes milk to 72 °C for 15 seconds. Pasteurization uses heat but does not make the food sterile. Reference: OpenStax Microbiology, 13.2 Using Physical Methods to Control Microorganisms (openstax.org/books/microbiology/pages/13-2-using-physical-methods-to-control-microorganisms).', '["Autoclave settings; the product would be sterile.","Kills pathogens, but some spoilage microbes survive.","Dry-heat sterilization.","Not used for pasteurizing milk."]'::jsonb, 1, 'verified'
