insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Plastic items such as gloves and IV tubing are commonly sterilized with:', '["Ultraviolet light","Ionizing radiation (e.g., gamma rays)","Boiling water","70% alcohol"]'::jsonb, 1, 'Ionizing radiation is used clinically to sterilize gloves, IV tubing, and other latex and plastic items. UV light is nonionizing and does not penetrate surfaces, plastics, or glass. Reference: OpenStax Microbiology, 13.2 Using Physical Methods to Control Microorganisms (openstax.org/books/microbiology/pages/13-2-using-physical-methods-to-control-microorganisms).', '["Works on surfaces only; poor penetration.","Penetrates packaging; used for heat-sensitive disposables.","Would melt or damage plastics and does not sterilize.","A disinfectant; does not kill spores."]'::jsonb, 1, 'verified'
