insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Why is 70% alcohol a better disinfectant than 100% alcohol?', '["100% alcohol is too flammable to use","Pure alcohol coagulates surface proteins too fast, blocking penetration into the cell","70% alcohol also kills endospores","100% alcohol evaporates too slowly"]'::jsonb, 1, 'Alcohols work better in water: at high concentrations they rapidly coagulate surface proteins, which prevents effective penetration of the cell. Reference: OpenStax Microbiology, 13.3 Using Chemicals to Control Microorganisms (openstax.org/books/microbiology/pages/13-3-using-chemicals-to-control-microorganisms).', '["Not the reason.","Water helps alcohol enter the cell and denature proteins inside.","Alcohol does not kill endospores at any concentration.","Pure alcohol evaporates faster, not slower."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'MICRO' and t.name = 'Lab Safety & Sterilization'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Why is 70% alcohol a better disinfectant than 100% alcohol?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Not the reason.","Water helps alcohol enter the cell and denature proteins inside.","Alcohol does not kill endospores at any concentration.","Pure alcohol evaporates faster, not slower."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["100% alcohol is too flammable to use","Pure alcohol coagulates surface proteins too fast, blocking penetration into the cell","70% alcohol also kills endospores","100% alcohol evaporates too slowly"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Why is 70% alcohol a better disinfectant than 100% alcohol?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Viruses are described as obligate intracellular parasites because they:', '["Can grow on any nutrient agar","Can only replicate inside a living host cell","Make their own ATP","Divide by binary fission"]'::jsonb, 1, 'Viruses are acellular and must infect a cellular host to survive and reproduce, which makes them obligate intracellular parasites. Reference: OpenStax Microbiology, 6.1 Viruses (openstax.org/books/microbiology/pages/6-1-viruses).', '["Viruses do not grow on agar.","They need host cell machinery to make proteins and copy their genome.","They have no metabolism of their own.","That is how bacteria divide."]'::jsonb, 1, 'verified'
