insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Hepatitis A virus is mainly transmitted by:', '["Blood transfusion","The fecal-oral route","Sexual contact only","Mosquito bites"]'::jsonb, 1, 'HAV is generally spread by the fecal-oral route, close personal contact, or contaminated water or food, while HBV is linked to infectious blood or body fluids. Reference: OpenStax Microbiology, 24.4 Viral Infections of the Gastrointestinal Tract (openstax.org/books/microbiology/pages/24-4-viral-infections-of-the-gastrointestinal-tract).', '["Mainly hepatitis B and C.","Contaminated food or water; no chronic infection.","Not the main route.","Spreads dengue, malaria, etc."]'::jsonb, 1, 'verified'
