insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The two main surface spike antigens of influenza virus are:', '["Hemagglutinin and neuraminidase","Fusion protein and nucleoprotein","Capsid and envelope","Reverse transcriptase and integrase"]'::jsonb, 0, 'Influenza''s main antigens are the spike proteins hemagglutinin (H) and neuraminidase (N); changes in them by antigenic drift and shift produce new strains. Reference: OpenStax Microbiology, 22.3 Viral Infections of the Respiratory Tract (openstax.org/books/microbiology/pages/22-3-viral-infections-of-the-respiratory-tract).', '["H binds sialic acid to enter cells; N releases new virus.","Found in other viruses or inside the virus.","Not spike antigens.","HIV enzymes."]'::jsonb, 1, 'verified'
