insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'A patient has had dengue-like fever for 3 days. Which test best confirms a current infection at this stage?', '["Dengue IgG antibody","Dengue NS1 antigen (or RT-PCR)","Widal test","Weil-Felix test"]'::jsonb, 1, 'NS1 antigen in serum during the first 7 days of illness indicates a current or recent dengue infection, and RT-PCR detects the RNA in days 0–7. IgM testing identifies most infections after day 3. Reference: CDC, Dengue Diagnosis and Testing (cdc.gov/dengue/hcp/diagnosis-testing).', '["Rises later; a high IgG early suggests secondary infection.","NS1 antigen is detectable in the first days of fever.","For typhoid fever.","For rickettsial infections."]'::jsonb, 2, 'verified'
