where s.code = 'MICRO' and t.name = 'Virology'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A patient has had dengue-like fever for 3 days. Which test best confirms a current infection at this stage?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
