insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'A person is anti-HBs positive but HBsAg and anti-HBc negative. This means:', '["Acute hepatitis B infection","Chronic hepatitis B infection","Immunity from hepatitis B vaccination","Immunity from a past natural infection"]'::jsonb, 2, 'Anti-HBs alone means vaccine immunity. Past natural infection would also show anti-HBc, which vaccines do not produce. Reference: CDC, Interpretation of Hepatitis B Serologic Test Results (cdc.gov/hepatitis-b/media/serologicchartv8.pdf).', '["HBsAg would be positive.","HBsAg would be positive for over 6 months.","The vaccine has only HBsAg, so only anti-HBs forms.","Anti-HBc would also be positive."]'::jsonb, 2, 'verified'
