select null, t.id, 'builtin', 'HBsAg positive, total anti-HBc positive, and IgM anti-HBc positive, with anti-HBs negative, indicates:', '["Acute hepatitis B infection","Immunity from vaccination","Resolved past infection","Susceptible, never infected"]'::jsonb, 0, 'HBsAg with IgM anti-HBc means acute infection; the same pattern with IgM anti-HBc negative means chronic infection. Reference: CDC, Interpretation of Hepatitis B Serologic Test Results (cdc.gov/hepatitis-b/media/serologicchartv8.pdf).', '["IgM anti-HBc marks a recent infection.","Vaccination gives anti-HBs only.","HBsAg would be negative and anti-HBs positive.","All markers would be negative."]'::jsonb, 2, 'verified'
