where s.code = 'MICRO' and t.name = 'Virology'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('HBsAg positive, total anti-HBc positive, and IgM anti-HBc positive, with anti-HBs negative, indicates:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["IgM anti-HBc marks a recent infection.","Vaccination gives anti-HBs only.","HBsAg would be negative and anti-HBs positive.","All markers would be negative."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Acute hepatitis B infection","Immunity from vaccination","Resolved past infection","Susceptible, never infected"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('HBsAg positive, total anti-HBc positive, and IgM anti-HBc positive, with anti-HBs negative, indicates:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));

commit;
